use serde_json::Value;
use std::collections::BTreeSet;

pub fn set_of(v: &Value, path: &[&str]) -> BTreeSet<String> {
    let mut cur = v;
    for p in path {
        match cur.get(p) {
            Some(next) => cur = next,
            None => return BTreeSet::new(),
        }
    }
    cur.as_array()
        .map(|a| a.iter().filter_map(|x| x.as_str()).map(str::to_string).collect())
        .unwrap_or_default()
}
